package com.mvt.backApp.user.service;
import com.mvt.backApp.common.exception.ApiException;import com.mvt.backApp.common.security.RoleNames;import com.mvt.backApp.security.model.AuthenticatedUser;import com.mvt.backApp.user.dto.*;import com.mvt.backApp.user.entity.*;import com.mvt.backApp.user.repository.*;
import lombok.RequiredArgsConstructor;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.util.stream.*;
@Service @RequiredArgsConstructor public class AdminUserService {private final UserRepository users;private final RoleRepository roles;private final PermissionRepository permissions;private final PasswordEncoder encoder;
 public record ManagedUserResponse(UUID userId,String email,String role,Set<String> permissions,boolean mustChangePassword){}
 @Transactional public ManagedUserResponse createAdmin(CreateAdminRequest r){subset(r.getPermissions());if(users.existsByEmailIgnoreCase(r.getEmail()))throw new ApiException("EMAIL_ALREADY_REGISTERED","error.registration.emailExists",409);Role role=roles.findByName(RoleNames.ADMIN).orElseThrow(()->new ApiException("ROLE_MISSING","error.system.roleMissing",500));User u=new User();u.setFirstName(r.getFirstName());u.setLastName(r.getLastName());u.setGender(r.getGender());u.setEmail(r.getEmail().toLowerCase(Locale.ROOT));u.setPasswordHash(encoder.encode(r.getTemporaryPassword()));u.setEmailVerified(true);u.setMustChangePassword(true);u.setRole(role);u.setDirectPermissions(resolve(r.getPermissions()));return view(users.save(u));}
 @Transactional public ManagedUserResponse assign(UUID id,AssignPermissionsRequest r){subset(r.getPermissions());User u=target(id);immutable(u);u.setDirectPermissions(resolve(r.getPermissions()));return view(users.save(u));}
 @Transactional public void changePassword(UUID id,ChangeManagedPasswordRequest r){User u=target(id);immutable(u);u.setPasswordHash(encoder.encode(r.getTemporaryPassword()));u.setMustChangePassword(true);users.save(u);}
 private void subset(Set<String> requested){Set<String> owned=((AuthenticatedUser)SecurityContextHolder.getContext().getAuthentication().getPrincipal()).getAuthorities().stream().map(a->a.getAuthority()).collect(Collectors.toSet());if(!owned.containsAll(requested))throw new ApiException("PERMISSION_DELEGATION_FORBIDDEN","error.permissions.notOwned",403);}
 private Set<Permission> resolve(Set<String> names){Set<Permission> found=new HashSet<>(permissions.findAllByNameIn(names));if(found.size()!=names.size())throw new ApiException("PERMISSION_UNKNOWN","error.permissions.unknown",400);return found;}
 private User target(UUID id){return users.findWithRoleAndPermissionsById(id).orElseThrow(()->new ApiException("USER_NOT_FOUND","error.user.notFound",404));}private void immutable(User u){if(RoleNames.SUPER_ADMIN.equals(u.getRole().getName()))throw new ApiException("SUPER_ADMIN_IMMUTABLE","error.permissions.superAdminImmutable",403);}private ManagedUserResponse view(User u){return new ManagedUserResponse(u.getId(),u.getEmail(),u.getRole().getName(),u.getDirectPermissions().stream().map(Permission::getName).collect(Collectors.toCollection(TreeSet::new)),u.isMustChangePassword());}}
